<?php
require_once __DIR__.'/app/lib/Db.php';require_once __DIR__.'/app/lib/Security.php';require_once __DIR__.'/app/lib/Entitlements.php';$pdo=Db::pdo();Security::start();$u=Security::user();if(!$u){header('Location: /login?next='.rawurlencode('/selection-projects'));exit;}Entitlements::requireFeature($pdo,$u,'selection_projects');$ctx=Entitlements::context($pdo,$u);$csrf=Security::csrf();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Selection Projects | TechSelectAI</title><style>body{font-family:Inter,Arial,sans-serif;background:#f6f8fb;color:#14213d;margin:0}main{max-width:1280px;margin:auto;padding:24px}.top{display:flex;justify-content:space-between;gap:12px;align-items:center}.grid{display:grid;grid-template-columns:320px 1fr;gap:18px}.card,.panel{background:#fff;border:1px solid #e4e9f0;border-radius:14px;padding:16px}.project{padding:12px;border:1px solid #e5e7eb;border-radius:10px;margin:8px 0;cursor:pointer}.project:hover{background:#f8fafc}.row{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}label{display:block;font-size:12px;font-weight:700;margin:8px 0 4px}input,select,textarea{width:100%;box-sizing:border-box;padding:9px;border:1px solid #cbd5e1;border-radius:8px}textarea{min-height:80px}button{border:0;border-radius:8px;padding:9px 12px;background:#1d4ed8;color:#fff;cursor:pointer}.secondary{background:#475569}.danger{background:#b91c1c}.muted{color:#64748b}.badge{display:inline-block;padding:3px 7px;border-radius:999px;background:#eef2ff;font-size:11px}.item{border:1px solid #e5e7eb;border-radius:10px;padding:10px;margin:8px 0}.brief{white-space:pre-wrap;background:#f8fafc;border-radius:10px;padding:12px;font-size:13px}.hidden{display:none}.notice{padding:10px;border-radius:10px;background:#eff6ff;margin-bottom:14px}@media(max-width:850px){.grid,.row{grid-template-columns:1fr}}</style></head><body><main><div class="top"><div><h1>Software Selection Projects</h1><p class="muted">Define requirements once, then reuse them for shortlist, Business Case, ROI/TCO, RFP and Decision Pack.</p></div><div><span class="badge"><?=htmlspecialchars($ctx['tier'])?></span> · <a href="/plans">Plans</a></div></div><div class="notice">AI-assisted discovery remains explicit: requirements imported from the guided consultation keep their source as AI-suggested or inferred until you confirm them.</div><div class="grid"><aside class="card"><h2>Your projects</h2><button onclick="newProject()">+ New project</button><div id="projects"></div></aside><section class="panel"><div id="empty"><h2>Select or create a project</h2><p class="muted">Registered accounts can save and resume projects. Pro enables advanced AI-assisted requirements.</p></div><div id="editor" class="hidden"><input type="hidden" id="pid"><h2 id="heading"></h2><div class="row"><div><label>Project name</label><input id="name"></div><div><label>Status</label><select id="status"><option>draft</option><option>active</option><option>shortlisting</option><option>decision_ready</option><option>archived</option></select></div><div><label>Linked consultation ID</label><input id="consultation_id" type="number" disabled></div></div><div class="row"><div><label>Company size</label><input id="company_size_band"></div><div><label>Industry</label><input id="industry_text"></div><div><label>Expected users</label><input id="expected_users" type="number"></div></div><div class="row"><div><label>Countries (2-letter codes)</label><input id="country_codes" placeholder="SA, AE, EG"></div><div><label>Deployment preference</label><input id="deployment_preference"></div><div><label>Implementation timeline</label><input id="implementation_timeline"></div></div><div class="row"><div><label>Budget min</label><input id="budget_min" type="number" step="0.01"></div><div><label>Budget max</label><input id="budget_max" type="number" step="0.01"></div><div><label>Currency / period</label><input id="budget_currency" placeholder="USD"><input id="budget_period" placeholder="annual" style="margin-top:5px"></div></div><label>Current systems (comma or line separated)</label><textarea id="current_systems"></textarea><label>Security / compliance requirements</label><textarea id="security_compliance"></textarea><label>Implementation capacity</label><input id="implementation_capacity"><label>Support requirements</label><textarea id="support_requirements"></textarea><label>Strategic / business objectives</label><textarea id="strategic_objectives"></textarea><p><button onclick="saveProject()">Save project</button></p><hr><h3>Requirements</h3><div class="row"><div><label>Requirement</label><input id="req_text"></div><div><label>Priority</label><select id="req_priority"><option value="mandatory">Mandatory</option><option value="important">Important</option><option value="preferred" selected>Preferred</option></select></div><div><label>Source</label><select id="req_source"><option value="user_entered">User entered</option><?php if($ctx['features']['advanced_requirements_builder']): ?><option value="ai_suggested">AI suggested</option><option value="inferred">Inferred</option><?php endif; ?></select></div></div><button onclick="addRequirement()">Add requirement</button><div id="requirements"></div><h3>Required integrations</h3><div class="row"><div><label>Integration</label><input id="int_name"></div><div><label>Priority</label><select id="int_priority"><option value="mandatory">Mandatory</option><option value="important">Important</option><option value="preferred" selected>Preferred</option></select></div><div><label>Source</label><select id="int_source"><option value="user_entered">User entered</option><?php if($ctx['features']['advanced_requirements_builder']): ?><option value="ai_suggested">AI suggested</option><option value="inferred">Inferred</option><?php endif; ?></select></div></div><button onclick="addIntegration()">Add integration</button><div id="integrations"></div><h3>Requirements Brief</h3><div class="brief" id="brief"></div></div><div id="msg"></div></section></div></main><script>
const csrf=<?=json_encode($csrf)?>;let current=null;
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}
async function api(url,opt={}){opt.headers={...(opt.headers||{}),'Content-Type':'application/json','X-CSRF-Token':csrf};let r=await fetch(url,opt);let d=await r.json().catch(()=>({error:'invalid_response'}));if(!r.ok)throw new Error(d.error||'request_failed');return d}
async function loadProjects(){try{let d=await api('/api/selection-projects');document.getElementById('projects').innerHTML=d.projects.map(p=>`<div class="project" onclick="openProject(${p.id})"><strong>${esc(p.name)}</strong><br><span class="badge">${esc(p.status)}</span><br><small class="muted">${esc(p.updated_at)}</small></div>`).join('')||'<p class="muted">No saved projects yet.</p>'}catch(e){msg(e.message)}}
async function newProject(){let name=prompt('Project name');if(!name)return;let consultation=prompt('Optional consultation ID to import structured context (leave blank if none)')||'';try{let d=await api('/api/selection-projects',{method:'POST',body:JSON.stringify({name,consultation_id:consultation||null,status:'draft'})});await loadProjects();render(d.project)}catch(e){msg(e.message)}}
async function openProject(id){try{let d=await api('/api/selection-projects/'+id);render(d.project)}catch(e){msg(e.message)}}
function listVal(v){return Array.isArray(v)?v.join(', '):''}
function render(p){current=p;document.getElementById('empty').classList.add('hidden');document.getElementById('editor').classList.remove('hidden');document.getElementById('pid').value=p.id;document.getElementById('heading').textContent=p.name;['name','status','company_size_band','industry_text','expected_users','deployment_preference','budget_min','budget_max','budget_currency','budget_period','implementation_capacity','implementation_timeline','support_requirements','strategic_objectives','consultation_id'].forEach(k=>{let e=document.getElementById(k);if(e)e.value=p[k]??''});document.getElementById('country_codes').value=listVal(p.country_codes_json);document.getElementById('current_systems').value=listVal(p.current_systems_json);document.getElementById('security_compliance').value=listVal(p.security_compliance_json);document.getElementById('requirements').innerHTML=p.requirements.map(r=>`<div class="item"><strong>${esc(r.requirement_text)}</strong> <span class="badge">${esc(r.priority)}</span> <span class="badge">${esc(r.source)}</span>${+r.user_confirmed?'<span class="badge">confirmed</span>':'<span class="badge">needs confirmation</span>'}<br><button class="danger" onclick="delChild('requirements',${r.id})">Remove</button></div>`).join('')||'<p class="muted">No requirements yet.</p>';document.getElementById('integrations').innerHTML=p.integrations.map(r=>`<div class="item"><strong>${esc(r.integration_name)}</strong> <span class="badge">${esc(r.priority)}</span> <span class="badge">${esc(r.source)}</span><br><button class="danger" onclick="delChild('integrations',${r.id})">Remove</button></div>`).join('')||'<p class="muted">No integrations yet.</p>';document.getElementById('brief').textContent=JSON.stringify(p.requirements_brief,null,2)}
function split(v){return v.split(/[,\n]/).map(x=>x.trim()).filter(Boolean)}
async function saveProject(){if(!current)return;let b={};['name','status','company_size_band','industry_text','expected_users','deployment_preference','budget_min','budget_max','budget_currency','budget_period','implementation_capacity','implementation_timeline','support_requirements','strategic_objectives'].forEach(k=>b[k]=document.getElementById(k).value);b.country_codes=split(document.getElementById('country_codes').value);b.current_systems=split(document.getElementById('current_systems').value);b.security_compliance=split(document.getElementById('security_compliance').value);try{let d=await api('/api/selection-projects/'+current.id,{method:'PUT',body:JSON.stringify(b)});render(d.project);await loadProjects();msg('Saved',true)}catch(e){msg(e.message)}}
async function addRequirement(){if(!current)return;let text=document.getElementById('req_text').value.trim();if(!text)return;let priority=document.getElementById('req_priority').value,source=document.getElementById('req_source').value;try{let d=await api(`/api/selection-projects/${current.id}/requirements`,{method:'POST',body:JSON.stringify({requirement_text:text,priority,is_mandatory:priority==='mandatory',source,user_confirmed:source==='user_entered'})});document.getElementById('req_text').value='';render(d.project)}catch(e){msg(e.message)}}
async function addIntegration(){if(!current)return;let name=document.getElementById('int_name').value.trim();if(!name)return;let priority=document.getElementById('int_priority').value,source=document.getElementById('int_source').value;try{let d=await api(`/api/selection-projects/${current.id}/integrations`,{method:'POST',body:JSON.stringify({integration_name:name,priority,is_mandatory:priority==='mandatory',source,user_confirmed:source==='user_entered'})});document.getElementById('int_name').value='';render(d.project)}catch(e){msg(e.message)}}
async function delChild(kind,id){if(!confirm('Remove this item?'))return;try{let d=await api(`/api/selection-projects/${current.id}/${kind}/${id}`,{method:'DELETE'});render(d.project)}catch(e){msg(e.message)}}
function msg(t,ok=false){let e=document.getElementById('msg');e.textContent=t;e.style.color=ok?'#166534':'#b91c1c'}loadProjects();
</script></body></html>